const CSS=".card{box-sizing:border-box;color:var(--ink);font:13px/1.35 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif}\n.card *{box-sizing:border-box}\n.wrap{position:relative;width:100%;height:100%;min-width:0;min-height:0;padding:10px;overflow:hidden}\n.card[data-size=\"6x3\"] .wrap,.card[data-size=\"6x6\"] .wrap{padding:12px}\n.view{display:flex;flex-direction:column;gap:8px;height:100%;min-width:0;min-height:0}\n.card button{font:inherit;color:inherit;cursor:pointer}\n.card button:disabled{opacity:.55;cursor:default}\n\n/* \u9876\u680f */\n.hd{display:flex;align-items:center;gap:6px;flex:none;min-width:0}\n.ttl{flex:1;min-width:0;font-weight:700;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.pill{flex:none;padding:2px 8px;border-radius:999px;border:1px solid var(--line);background:var(--panel-paper);color:var(--muted);font-size:11px;font-weight:600;white-space:nowrap}\n.pill.hot{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n.add{flex:none;display:inline-flex;align-items:center;justify-content:center;height:28px;min-width:28px;padding:0 8px;border:0;border-radius:8px;background:var(--accent);color:var(--on-accent);font-weight:700}\n.add .plus{font-size:16px;line-height:1}\n.add .addt{font-size:12px;white-space:pre}\n.back{flex:none;width:30px;height:30px;padding:0;border:1px solid var(--line);border-radius:8px;background:var(--button-paper,var(--panel-paper));color:var(--ink);font-size:18px;line-height:1}\n\n/* \u7edf\u8ba1\u6761\uff08\u4ec5\u5927\u5361\uff09 */\n.stats{display:none;flex:none;gap:8px}\n.stat{flex:1;min-width:0;padding:6px 8px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper)}\n.sv{font-size:20px;font-weight:700;line-height:1.1}\n.sl{font-size:11px;color:var(--muted)}\n\n/* \u5217\u8868 */\n.list{flex:1;min-height:0;min-width:0;overflow-y:auto;overflow-x:hidden;display:flex;flex-direction:column;gap:6px;padding-right:2px}\n.row{flex:none;display:flex;align-items:center;gap:6px;min-width:0;padding:6px 6px 6px 8px;border:1px solid var(--line);border-left:3px solid var(--line);border-radius:10px;background:var(--panel-paper)}\n.row.over,.row.today{border-left-color:var(--accent);background:var(--soft)}\n.row.soon{border-left-color:var(--accent-alt)}\n.info{flex:1;min-width:0;display:block;padding:0;border:0;background:transparent;text-align:left;color:var(--ink)}\n.nm{display:flex;align-items:baseline;gap:6px;min-width:0}\n.nmt{min-width:0;font-weight:600;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.iv{flex:none;font-size:11px;color:var(--muted);white-space:nowrap}\n.dt{margin-top:1px;font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.dt>span+span::before{content:\" \u00b7 \"}\n.st{color:var(--ink);font-weight:700}\n.row.new .st{font-weight:600;color:var(--muted)}\n.done{flex:none;min-width:46px;height:32px;padding:0 8px;border:0;border-radius:8px;background:var(--accent);color:var(--on-accent);font-weight:600;font-size:12px;white-space:nowrap}\n.done.again{background:var(--button-paper,var(--panel-paper));color:var(--ink);border:1px solid var(--line)}\n\n/* \u7a7a\u72b6\u6001 */\n.empty{flex:1;min-height:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;text-align:center;padding:4px;overflow:auto}\n.et{font-weight:700;font-size:14px}\n.es{font-size:12px;color:var(--muted)}\n\n/* \u901a\u7528\u6309\u94ae */\n.btn{flex:1;min-width:0;height:32px;padding:0 10px;border:1px solid var(--line);border-radius:8px;background:var(--button-paper,var(--panel-paper));color:var(--ink);font-weight:600;font-size:13px;white-space:nowrap}\n.btn.primary{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n.btn.danger{background:var(--ink);border-color:var(--ink);color:var(--paper)}\n.link{flex:none;padding:2px 4px;border:0;background:transparent;color:var(--ink);font-size:12px;text-decoration:underline}\n\n/* \u8868\u5355\u4e0e\u8be6\u60c5 */\n.body{flex:1;min-height:0;min-width:0;overflow-y:auto;overflow-x:hidden;padding-right:2px}\n.form{display:grid;grid-template-columns:minmax(0,1fr);gap:10px;align-content:start}\n.fld{display:flex;flex-direction:column;gap:4px;min-width:0}\n.fl,.sh{font-size:12px;font-weight:600;color:var(--muted)}\n.in{width:100%;min-width:0;height:32px;padding:0 8px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);font:inherit;font-size:13px}\n.in:focus{outline:2px solid var(--accent);outline-offset:0}\n.per{display:flex;align-items:center;gap:6px}\n.every{flex:none;font-size:13px}\n.in.num{flex:1 1 60px;max-width:96px}\n.in.unit{flex:1 1 70px;max-width:110px}\n.chips{display:flex;flex-wrap:wrap;gap:6px}\n.chip{height:26px;padding:0 10px;border:1px solid var(--line);border-radius:999px;background:var(--soft);color:var(--ink);font-size:12px}\n.hint{font-size:11px;color:var(--muted)}\n.err{padding:6px 8px;border:1px solid var(--ink);border-radius:8px;font-size:12px;font-weight:600}\n.ft{flex:none;display:flex;flex-wrap:wrap;gap:6px}\n.ask{flex:1 0 100%;font-size:12px;font-weight:600;white-space:normal}\n.kvs{display:flex;flex-direction:column;gap:4px;margin-bottom:10px}\n.kv{display:flex;gap:8px;align-items:baseline;min-width:0}\n.k{flex:none;width:58px;font-size:12px;color:var(--muted)}\n.v{flex:1;min-width:0;font-size:13px;overflow-wrap:anywhere}\n.sec{margin-bottom:10px}\n.sh{display:flex;align-items:center;justify-content:space-between;gap:6px;margin-bottom:4px}\n.bf{display:flex;gap:6px}\n.bf .in{flex:1}\n.bf .btn{flex:none;min-width:56px}\n.hist{display:flex;flex-direction:column;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper)}\n.hi{display:flex;justify-content:space-between;align-items:center;gap:6px;padding:5px 8px;font-size:12px;border-top:1px solid var(--line)}\n.hi:first-child{border-top:0}\n.tag{padding:0 6px;border-radius:999px;background:var(--soft);font-size:11px;color:var(--ink)}\n\n/* \u63d0\u793a */\n.toast{position:absolute;left:10px;right:10px;bottom:10px;padding:7px 10px;border-radius:10px;background:var(--ink);color:var(--paper);font-size:12px;font-weight:600;pointer-events:none;border:1px solid var(--line);animation:chToast 4s ease forwards}\n@keyframes chToast{0%{opacity:0;transform:translateY(6px)}8%{opacity:1;transform:none}85%{opacity:1}100%{opacity:0;visibility:hidden}}\n\n/* 194x194\uff1a\u7d27\u51d1\u4e24\u884c\uff0c\u7701\u7565\u5468\u671f/\u661f\u671f/\u4e0a\u6b21 */\n.card[data-size=\"3x3\"] .iv,\n.card[data-size=\"3x3\"] .wd,\n.card[data-size=\"3x3\"] .nxl,\n.card[data-size=\"3x3\"] .ls{display:none}\n.card[data-size=\"3x3\"] .addt{display:none}\n.card[data-size=\"3x3\"] .row{padding:5px 5px 5px 7px}\n.card[data-size=\"3x3\"] .btn{padding:0 4px;font-size:12px}\n.card[data-size=\"3x3\"] .kvs{margin-bottom:8px}\n.card[data-size=\"3x3\"] .k{width:52px}\n\n/* 194x404\uff1a\u7a84\u800c\u9ad8\uff0c\u4e0b\u6b21\u65e5\u671f/\u72b6\u6001/\u4e0a\u6b21\u5404\u5360\u4e00\u884c */\n.card[data-size=\"3x6\"] .iv,\n.card[data-size=\"3x6\"] .addt{display:none}\n.card[data-size=\"3x6\"] .dt{white-space:normal}\n.card[data-size=\"3x6\"] .dt>span{display:block}\n.card[data-size=\"3x6\"] .dt>span+span::before{content:none}\n.card[data-size=\"3x6\"] .row{padding:8px 6px 8px 8px}\n.card[data-size=\"3x6\"] .btn{padding:0 4px;font-size:12px}\n.card[data-size=\"3x6\"] .k{width:52px}\n\n/* 404x194\uff1a\u5bbd\u800c\u77ee\uff0c\u4e00\u884c\u4e00\u9879 */\n.card[data-size=\"6x3\"] .iv,\n.card[data-size=\"6x3\"] .ls{display:none}\n.card[data-size=\"6x3\"] .info{display:flex;align-items:baseline;gap:10px}\n.card[data-size=\"6x3\"] .nm{flex:0 1 38%}\n.card[data-size=\"6x3\"] .dt{flex:1;margin-top:0;min-width:0}\n.card[data-size=\"6x3\"] .row{padding:4px 6px 4px 8px}\n.card[data-size=\"6x3\"] .done{height:30px}\n.card[data-size=\"6x3\"] .form{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:8px 14px}\n.card[data-size=\"6x3\"] .form .fld:nth-child(2){grid-row:span 2}\n.card[data-size=\"6x3\"] .form .err{grid-column:1/-1}\n.card[data-size=\"6x3\"] .chips{gap:4px}\n.card[data-size=\"6x3\"] .chip{padding:0 8px}\n\n/* 404x404\uff1a\u7edf\u8ba1\u6761 + \u5b8c\u6574\u4fe1\u606f */\n.card[data-size=\"6x6\"] .stats{display:flex}\n.card[data-size=\"6x6\"] .ttl{font-size:16px}\n.card[data-size=\"6x6\"] .nmt{font-size:14px}\n.card[data-size=\"6x6\"] .dt{font-size:12px}\n.card[data-size=\"6x6\"] .row{padding:9px 8px 9px 10px}\n.card[data-size=\"6x6\"] .done{min-width:56px;height:34px;font-size:13px}\n.card[data-size=\"6x6\"] .in,.card[data-size=\"6x6\"] .btn{height:34px}\n";
/* 家务记录：纯逻辑助手（日期计算、排序、状态） */
const CH_WD=['日','一','二','三','四','五','六'];
const CH_UNIT={day:'天',week:'周',month:'个月'};

function chPad(n){return String(n).padStart(2,'0');}
function chItems(s){return (s&&Array.isArray(s.chores))?s.chores:[];}
function chHist(c){return Array.isArray(c.history)?c.history:[];}

function chParse(s){
  const m=/^(\d{4})-(\d{2})-(\d{2})/.exec(s||'');
  return m?{y:+m[1],m:+m[2],d:+m[3]}:null;
}
function chNow(){
  const t=new Date();
  return t.getFullYear()+'-'+chPad(t.getMonth()+1)+'-'+chPad(t.getDate())+' '+chPad(t.getHours())+':'+chPad(t.getMinutes());
}
function chInsert(h,stamp){
  const a=(Array.isArray(h)?h.slice():[]);
  a.push(stamp);
  a.sort();
  a.reverse();
  return a.slice(0,100);
}
function chAddInterval(dateStr,n,unit){
  const p=chParse(dateStr);
  if(!p)return null;
  let y=p.y,m=p.m-1,d=p.d;
  let t;
  if(unit==='month'){
    const tm=m+n;
    y=y+Math.floor(tm/12);
    m=((tm%12)+12)%12;
    const dim=new Date(y,m+1,0).getDate();
    t=new Date(y,m,Math.min(d,dim));
  }else{
    t=new Date(y,m,d+(unit==='week'?7*n:n));
  }
  return t.getFullYear()+'-'+chPad(t.getMonth()+1)+'-'+chPad(t.getDate());
}
function chDiff(a,b){
  const p=chParse(a),q=chParse(b);
  if(!p||!q)return 0;
  return Math.round((Date.UTC(q.y,q.m-1,q.d)-Date.UTC(p.y,p.m-1,p.d))/86400000);
}
function chWeekday(s){
  const p=chParse(s);
  if(!p)return '';
  return '周'+CH_WD[new Date(p.y,p.m-1,p.d).getDay()];
}
/* 11月7日（跨年份时带年） */
function chMD(s,today){
  const p=chParse(s),t=chParse(today);
  if(!p)return '';
  return (t&&p.y!==t.y?p.y+'年':'')+p.m+'月'+p.d+'日';
}
/* 11-01 14:20（跨年份时带年） */
function chShortStamp(s,today){
  const p=chParse(s),t=chParse(today);
  if(!p)return '';
  const time=s.length>10?' '+s.slice(11,16):'';
  return (t&&p.y!==t.y?p.y+'-':'')+chPad(p.m)+'-'+chPad(p.d)+time;
}
function chEvery(c){
  const n=Number(c.n)||1;
  if(c.unit==='day'&&n===1)return '每天';
  if(c.unit==='week'&&n===1)return '每周';
  if(c.unit==='month'&&n===1)return '每个月';
  return '每'+n+(CH_UNIT[c.unit]||'天');
}
/* 一项家务的派生状态：上次、下次、距今天数 */
function chInfo(c,today){
  const h=chHist(c).slice().sort().reverse();
  const last=h.length?h[0]:null;
  const n=Math.max(1,Number(c.n)||1);
  const next=last?chAddInterval(last.slice(0,10),n,c.unit):null;
  const diff=next?chDiff(today,next):null;
  let kind='new',label='待首次完成';
  if(last){
    if(diff<0){kind='over';label='逾期'+(-diff)+'天';}
    else if(diff===0){kind='today';label='今天该做';}
    else if(diff===1){kind='soon';label='明天';}
    else if(diff<=3){kind='soon';label=diff+'天后';}
    else{kind='ok';label=diff+'天后';}
  }
  return {last,next,diff,kind,label,doneToday:!!last&&last.slice(0,10)===today,count:h.length};
}
function chSort(items,today){
  const rows=items.map(c=>({c,i:chInfo(c,today)}));
  rows.sort((a,b)=>{
    const an=a.i.next,bn=b.i.next;
    if(an&&bn){
      if(an!==bn)return an<bn?-1:1;
    }else if(an||bn){
      return an?-1:1;
    }
    return String(a.c.name).localeCompare(String(b.c.name));
  });
  return rows;
}

/* 动作：完成 / 跳转 */
function chGo(ctx,patch){
  const {ui,redraw}=ctx;
  ui.toast=null;
  ui.err=null;
  ui.undoArm=false;
  Object.keys(patch).forEach(k=>{ui[k]=patch[k];});
  redraw();
}
function chOpenForm(ctx,id){
  const c=id?chItems(ctx.state).find(x=>x.id===id):null;
  chGo(ctx,{
    view:'form',formId:id||null,saving:false,
    draft:c?{name:c.name,n:String(c.n),unit:c.unit,last:''}:{name:'',n:'',unit:'day',last:''}
  });
}
function chComplete(ctx,c){
  const {update,ui,redraw,day}=ctx;
  const stamp=chNow();
  ui.toast=null;
  return update(s=>({...s,chores:chItems(s).map(x=>x.id===c.id?{...x,history:chInsert(x.history,stamp)}:x)}))
    .then(()=>{
      const nx=chAddInterval(stamp.slice(0,10),Number(c.n)||1,c.unit);
      ui.toast='已记录「'+c.name+'」'+stamp.slice(5)+'，下次 '+chMD(nx,day())+' '+chWeekday(nx);
      ui.err=null;
      redraw();
    })
    .catch(()=>{ui.toast='保存失败，请重试';redraw();});
}

/* 列表视图 */
function chStat(el,label,val){
  return el('div',{class:'stat'},el('div',{class:'sv'},String(val)),el('div',{class:'sl'},label));
}
function chRow(ctx,r,today){
  const {el}=ctx;
  const c=r.c,i=r.i;
  const dt=[];
  if(i.kind==='new'){
    dt.push(el('span',{class:'st'},'待首次完成'));
    dt.push(el('span',{class:'ls'},chEvery(c)));
  }else{
    dt.push(el('span',{class:'nx'},
      el('span',{class:'nxl'},'下次 '),chMD(i.next,today),
      el('span',{class:'wd'},' '+chWeekday(i.next))));
    dt.push(el('span',{class:'st'},i.label));
    dt.push(el('span',{class:'ls'},'上次 '+chShortStamp(i.last,today)));
  }
  const full=c.name+'：'+chEvery(c)+(i.next?'，下次 '+chMD(i.next,today)+'（'+i.label+'）':'，尚未完成过');
  return el('div',{class:'row '+i.kind,role:'listitem'},
    el('button',{class:'info',type:'button',title:full,'aria-label':'查看详情：'+full,onclick:()=>chGo(ctx,{view:'detail',detailId:c.id,bf:'',confirmDel:false})},
      el('div',{class:'nm'},el('span',{class:'nmt'},c.name),el('span',{class:'iv'},chEvery(c))),
      el('div',{class:'dt'},...dt)),
    el('button',{class:'done'+(i.doneToday?' again':''),type:'button','aria-label':'完成：'+c.name,
      title:i.doneToday?'今天已记录，再点会再记一次':'记下这次完成的时间',
      onclick:()=>chComplete(ctx,c)},i.doneToday?'已完成':'完成'));
}
function chList(ctx){
  const {el,state,day}=ctx;
  const today=day();
  const rows=chSort(chItems(state),today);
  const over=rows.filter(r=>r.i.kind==='over').length;
  const td=rows.filter(r=>r.i.kind==='today').length;
  const soon=rows.filter(r=>r.i.next&&r.i.diff>0&&r.i.diff<=7).length;
  const due=over+td;
  const head=el('div',{class:'hd'},
    el('div',{class:'ttl'},'家务记录'),
    ...(rows.length?[el('div',{class:'pill'+(due?' hot':'')},due?'待做 '+due:'全完成')]:[]),
    el('button',{class:'add',type:'button','aria-label':'添加家务',onclick:()=>chOpenForm(ctx,null)},
      el('span',{class:'plus'},'+'),el('span',{class:'addt'},' 添加')));
  let body;
  if(!rows.length){
    body=el('div',{class:'empty'},
      el('div',{class:'et'},'还没有家务项'),
      el('div',{class:'es'},'比如洗床单、打扫卫生、清理冰箱，设好多久做一次。'),
      el('button',{class:'btn primary',type:'button',onclick:()=>chOpenForm(ctx,null)},'添加第一项'));
  }else{
    body=el('div',{class:'list',role:'list'},...rows.map(r=>chRow(ctx,r,today)));
  }
  return el('div',{class:'view'},head,
    ...(rows.length?[el('div',{class:'stats'},chStat(el,'已逾期',over),chStat(el,'今天',td),chStat(el,'7天内',soon),chStat(el,'共计',rows.length))]:[]),
    body);
}

/* 添加 / 编辑表单 */
function chField(el,label,...kids){
  return el('label',{class:'fld'},el('span',{class:'fl'},label),...kids);
}
function chForm(ctx){
  const {el,ui,commit,redraw,day,uid}=ctx;
  const d=ui.draft||{name:'',n:'',unit:'day',last:''};
  ui.draft=d;
  const editing=!!ui.formId;
  const setErr=m=>{ui.err=m;redraw();};
  const back=()=>{
    if(editing)chGo(ctx,{view:'detail',detailId:ui.formId,draft:null,formId:null});
    else chGo(ctx,{view:'list',draft:null,formId:null});
  };
  const save=()=>{
    if(ui.saving)return;
    const name=String(d.name||'').trim();
    const n=Number(d.n);
    if(!name)return setErr('请填写家务名称');
    if(!(d.n!==''&&Number.isInteger(n)&&n>=1&&n<=999))return setErr('周期请填 1–999 的整数');
    if(!editing&&d.last&&d.last>day())return setErr('上次完成日期不能晚于今天');
    ui.saving=true;
    ui.err=null;
    const id=ui.formId;
    const nextUi=editing
      ?{view:'detail',detailId:id,formId:null,draft:null,saving:false,err:null,toast:null}
      :{view:'list',formId:null,draft:null,saving:false,err:null,toast:null};
    commit(s=>{
      if(editing){
        return {...s,chores:chItems(s).map(x=>x.id===id?{...x,name,n,unit:d.unit}:x)};
      }
      const item={id:uid(),name,n,unit:d.unit,history:d.last?[d.last]:[],created:day()};
      return {...s,chores:[...chItems(s),item]};
    },nextUi).catch(()=>{ui.saving=false;ui.err='保存失败，请重试';redraw();});
  };
  const onEnter=e=>{if(e.key==='Enter'){e.preventDefault();save();}};
  const preset=(n,unit)=>()=>{d.n=String(n);d.unit=unit;redraw();};
  const unitSel=el('select',{class:'in unit','aria-label':'周期单位',onchange:e=>{d.unit=e.target.value;}},
    el('option',{value:'day'},'天'),el('option',{value:'week'},'周'),el('option',{value:'month'},'个月'));
  unitSel.value=d.unit;
  const chips=[['每天',1,'day'],['每周',1,'week'],['每两周',2,'week'],['每个月',1,'month']];
