    if(v>today)return fail('补记日期不能晚于今天');
    ui.err=null;ui.undoArm=false;ui.toast=null;
    update(s=>({...s,chores:chItems(s).map(x=>x.id===c.id?{...x,history:chInsert(x.history,v)}:x)}))
      .then(()=>{ui.bf='';redraw();})
      .catch(()=>fail('保存失败，请重试'));
  };
  const undo=()=>{
    if(!ui.undoArm){ui.undoArm=true;redraw();return;}
    ui.undoArm=false;ui.err=null;ui.toast=null;
    update(s=>({...s,chores:chItems(s).map(x=>x.id===c.id?{...x,history:chHist(x).slice().sort().reverse().slice(1)}:x)}))
      .catch(()=>fail('保存失败，请重试'));
  };
  const remove=()=>{
    commit(s=>({...s,chores:chItems(s).filter(x=>x.id!==c.id)}),
      {view:'list',detailId:null,confirmDel:false,bf:'',err:null,toast:null,undoArm:false})
      .catch(()=>fail('删除失败，请重试'));
  };
  const nextTxt=i.next
    ?[chMD(i.next,today)+' '+chWeekday(i.next)+' · ',el('b',{},i.label)]
    :['点「完成」后开始计算'];
  const lastTxt=i.last?(i.last.length>10?i.last:i.last+'（仅日期）'):'尚未完成过';
  const footer=ui.confirmDel
    ?el('div',{class:'ft'},
        el('div',{class:'ask'},'删除「'+c.name+'」及其记录？'),
        el('button',{class:'btn',type:'button',onclick:()=>{ui.confirmDel=false;redraw();}},'取消'),
        el('button',{class:'btn danger',type:'button',onclick:remove},'确认删除'))
    :el('div',{class:'ft'},
        el('button',{class:'btn primary',type:'button',onclick:()=>chComplete(ctx,c)},i.doneToday?'再记一次':'完成'),
        el('button',{class:'btn',type:'button',onclick:()=>chOpenForm(ctx,c.id)},'编辑'),
        el('button',{class:'btn',type:'button',onclick:()=>{ui.confirmDel=true;redraw();}},'删除'));
  return el('div',{class:'view'},
    el('div',{class:'hd'},
      el('button',{class:'back',type:'button','aria-label':'返回列表',onclick:back},'‹'),
      el('div',{class:'ttl',title:c.name},c.name)),
    el('div',{class:'body'},
      el('div',{class:'kvs'},
        chKV(el,'周期',chEvery(c)),
        chKV(el,'上次完成',lastTxt),
        chKV(el,'下次应做',...nextTxt)),
      el('div',{class:'sec'},
        el('div',{class:'sh'},'补记以前的完成日期'),
        el('div',{class:'bf'},
          el('input',{class:'in',type:'date',value:ui.bf||'',max:today,'aria-label':'补记日期',
            oninput:e=>{ui.bf=e.target.value;},onchange:e=>{ui.bf=e.target.value;}}),
          el('button',{class:'btn',type:'button',onclick:backfill},'补记'))),
      ...(ui.err?[el('div',{class:'err',role:'alert'},'⚠ '+ui.err)]:[]),
      el('div',{class:'sec'},
        el('div',{class:'sh'},
          el('span',{},'完成记录（'+hist.length+'）'),
          ...(hist.length?[el('button',{class:'link',type:'button',onclick:undo},ui.undoArm?'再点一次确认撤销':'撤销最近一次')]:[])),
        hist.length
          ?el('div',{class:'hist'},...hist.map((h,k)=>el('div',{class:'hi'},
              el('span',{},h.length>10?h:h+'（仅日期）'),
              ...(k===0?[el('span',{class:'tag'},'最近')]:[]))))
          :el('div',{class:'es'},'还没有完成记录'))),
    footer);
}

/* 入口 */
function mount(ctx){
  const {root,el,state,ui}=ctx;
  const items=chItems(state);
  let view=ui.view||'list';
  if(view==='detail'&&!items.some(x=>x.id===ui.detailId))view='list';
  if(view==='form'&&ui.formId&&!items.some(x=>x.id===ui.formId))view='list';
  const page=view==='form'?chForm(ctx):view==='detail'?chDetail(ctx):chList(ctx);
  root.appendChild(el('div',{class:'wrap'},page,
    ...(ui.toast?[el('div',{class:'toast',role:'status'},ui.toast)]:[])));
}

